import{c as o,$ as n,Q as a,j as i,g as t,o as s,n as l,m as c}from"./chunks/framework.Ce_49mA8.js";const v=JSON.parse('{"title":"Customer Directory","description":"Practical guide to managing the workshop customer directory in OmniCraft ERP — contact management, automated phone formatting, notes, and service order integration.","frontmatter":{"title":"Customer Directory","description":"Practical guide to managing the workshop customer directory in OmniCraft ERP — contact management, automated phone formatting, notes, and service order integration.","datePublished":"2026-11-15","dateModified":"2026-11-15","order":13},"headers":[],"relativePath":"docs/spaces/services/clients.md","filePath":"docs/spaces/services/clients.md","lastUpdated":1794700800000}'),d={name:"docs/spaces/services/clients.md"},u={id:"customer-directory-client-records-contact-management",tabindex:"-1"};function p(m,e,h,g,f,y){const r=n("DocIcon");return a(),i("div",null,[t("h1",u,[s(r,{name:"about"}),e[0]||(e[0]=l(" Customer Directory: Client Records & Contact Management ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#customer-directory-client-records-contact-management","aria-label":'Permalink to "Customer Directory: Client Records & Contact Management"'},"​",-1))]),e[2]||(e[2]=c('<p>In the service and repair industry, repeat customers form the bedrock of workshop financial resilience. While a craft manufacturing studio can distribute batches through anonymous retail transactions, a service shop thrives on durable relationships: regular contractor fleet maintenance, seasonal equipment tune-ups, and recurring visits from satisfied clients.</p><p>When customer records reside in personal smartphone contacts, get lost across messenger chats, or pile up on handwritten index cards, the workshop incurs silent operational friction. Replacing a phone or losing a device wipes out customer history, client preferences slip through the cracks, and past warranty maintenance records disappear.</p><p>In <strong>OmniCraft ERP</strong>, the Services workspace elevates customer management into a centralized native tool. The <strong>&quot;Clients&quot;</strong> tab allows you to maintain an orderly counterparty registry, retrieve contact details in seconds, and preserve service histories tied directly to work orders.</p><hr><h2 id="tab-location-and-user-interface-overview" tabindex="-1">Tab Location and User Interface Overview <a class="header-anchor" href="#tab-location-and-user-interface-overview" aria-label="Permalink to &quot;Tab Location and User Interface Overview&quot;">​</a></h2><p>Within the Services workspace, the customer directory occupies a dedicated slot in the main top navigation menu:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Workshop] ➔ [Warehouse] ➔ [Services] ➔ [Orders] ➔ [Clients] ➔ [Storefront] ➔ [DDS] ➔ [Capital] ➔ [Analytics] ➔ [Settings]</span></span></code></pre></div><p>The workspace screen is optimized for instant contact lookups:</p><ul><li><strong>Top Control Bar:</strong> Features an instant search field with a one-click query reset button and the <strong>&quot;New Client&quot;</strong> button;</li><li><strong>Customer Card Desk:</strong> A clean card list where each entry presents: <ul><li>Customer full name or contractor/business organization name;</li><li>Standardized formatted telephone number for swift communication;</li><li>Operational notes, preferred channels, and equipment specifics;</li><li>Card editing control (pencil icon);</li><li>Safe non-destructive deletion control (trash icon).</li></ul></li></ul><hr><h2 id="step-by-step-guide-registering-a-new-customer" tabindex="-1">Step-by-Step Guide: Registering a New Customer <a class="header-anchor" href="#step-by-step-guide-registering-a-new-customer" aria-label="Permalink to &quot;Step-by-Step Guide: Registering a New Customer&quot;">​</a></h2><p>Creating a customer profile takes place during the initial intake consultation or when receiving incoming equipment on the bench.</p><ol><li>Navigate to the <strong>&quot;Clients&quot;</strong> tab and click the <strong>&quot;New Client&quot;</strong> button in the upper-right corner.</li><li>In the modal dialog, enter the required details: <ul><li><strong>&quot;Client Name&quot;:</strong> Full name of private owner, technician handle, or company name (<em>&quot;Alex Voronov (StroyMontaj LLC)&quot;</em>);</li><li><strong>&quot;Phone&quot;:</strong> Direct customer telephone number. The software automatically applies input formatting masks (<code>+7 900 123-45-67</code>), eliminating typing typos;</li><li><strong>&quot;Notes&quot;:</strong> Practical collaboration details (preferred messaging handles, site delivery addresses, fleet specifics, or custom terms).</li></ul></li><li>Click the <strong>&quot;Save&quot;</strong> button.</li></ol><p>The new customer instantly joins your registry and becomes available in all service order intake dialogs.</p><div class="info custom-block"><p class="custom-block-title">Standardized Phone Formatting Mask</p><p>The application automatically normalizes entered telephone numbers to a uniform standard. Regardless of how the technician keys the digits, the software stores and renders an orderly format. This prevents duplicate contact entries in your database.</p></div><hr><h2 id="directory-management-search-editing-and-soft-delete" tabindex="-1">Directory Management: Search, Editing, and Soft Delete <a class="header-anchor" href="#directory-management-search-editing-and-soft-delete" aria-label="Permalink to &quot;Directory Management: Search, Editing, and Soft Delete&quot;">​</a></h2><p>As your workshop scales past hundreds of customer accounts, effortless search speed becomes critical:</p><ul><li><strong>On-the-Fly Search:</strong> Type starting letters of a name, telephone digits, or note fragments into the search field. The directory filters with zero latency. The cross icon on the right resets the filter instantly.</li><li><strong>Editing Profiles:</strong> Click the pencil icon on any customer card to update telephone numbers, adjust notes, or refresh corporate billing details.</li><li><strong>Soft Delete:</strong> Clicking the trash icon triggers a confirmation prompt: <em>&quot;Are you sure you want to delete this client?&quot;</em>.</li></ul><div class="info custom-block"><p class="custom-block-title">Historical Data Protection (Zero-Destruction)</p><p>Client deletion in OmniCraft ERP is non-destructive (<code>is_deleted = 1</code>). The record is hidden from active autocomplete pickers but remains permanently in your database. All previously finalized work orders, cash register transactions (DDS), and warranty records preserve complete client identity snapshots and historical financial sums.</p></div><hr><h2 id="cross-module-integration-clients-➔-service-orders" tabindex="-1">Cross-Module Integration: Clients ➔ Service Orders <a class="header-anchor" href="#cross-module-integration-clients-➔-service-orders" aria-label="Permalink to &quot;Cross-Module Integration: Clients ➔ Service Orders&quot;">​</a></h2><p>In OmniCraft ERP, the customer directory operates not as an isolated address book, but as an integrated operational registry:</p><ol><li><strong>Instant Selection on Intake:</strong> When initiating a new ticket in the <strong>&quot;Orders&quot;</strong> tab, simply select the customer from the picker list. The engine automatically links the order to the customer profile.</li><li><strong>Customer Name Snapshot (<code>client_name_snapshot</code>):</strong> Upon order creation, the system saves an exact text snapshot of the client name into the work order record. If the customer organization changes its name years later, archive orders maintain the exact legal identity in effect at the time of repair.</li><li><strong>Warranty and Service History:</strong> All open and completed tickets reference the client ID, allowing technicians to review past component replacements in seconds during repeat check-ins.</li></ol><hr><h2 id="local-privacy-and-autonomous-confidentiality" tabindex="-1">Local Privacy and Autonomous Confidentiality <a class="header-anchor" href="#local-privacy-and-autonomous-confidentiality" aria-label="Permalink to &quot;Local Privacy and Autonomous Confidentiality&quot;">​</a></h2><p>For an independent craft workshop or repair shop, the customer contact base represents core commercial equity. Leaking customer contact lists to competitors or cloud brokers inflicts irreversible business harm.</p><p>OmniCraft ERP enforces uncompromising local privacy:</p><ul><li><strong>Strict Local Storage:</strong> Your client database resides exclusively on your workstation within an isolated, local SQLite database file;</li><li><strong>Zero External Cloud Transfers:</strong> The software never uploads contact lists, phone numbers, or notes to third-party CRM servers or analytics hubs;</li><li><strong>No Recurring Contact Subscriptions:</strong> You never pay fees based on contact volume. Maintain 50 accounts or 10,000 clients with zero subscription limits;</li><li><strong>Autonomous Backup Workflow:</strong> Backup archives are created locally in a single click under the &quot;Settings&quot; tab and can be stored securely on an external drive.</li></ul><hr><h2 id="client-field-reference-matrix" tabindex="-1">Client Field Reference Matrix <a class="header-anchor" href="#client-field-reference-matrix" aria-label="Permalink to &quot;Client Field Reference Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Input Field</th><th style="text-align:left;">Parameter Purpose</th><th style="text-align:left;">Format &amp; Validation</th><th style="text-align:left;">Workshop Recommendation</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Client Name</strong></td><td style="text-align:left;">Primary identifier in work orders</td><td style="text-align:left;">Text string (up to 100 characters)</td><td style="text-align:left;">Combine individual name and company: <em>&quot;Alex Voronov (Crew 3)&quot;</em></td></tr><tr><td style="text-align:left;"><strong>Phone</strong></td><td style="text-align:left;">Direct line for repair updates</td><td style="text-align:left;">Formatted telephone mask</td><td style="text-align:left;">Verify during intake to ensure defect approvals can be sent</td></tr><tr><td style="text-align:left;"><strong>Notes</strong></td><td style="text-align:left;">Operational and technical context</td><td style="text-align:left;">Multi-line free text</td><td style="text-align:left;">Record equipment fleet quirks and communication rules</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Master Craftsman Advice: Record Specifics Immediately at Intake</p><p>Never rely on memory in the heat of daily repair traffic. If a customer specifically requests <em>&quot;return replaced worn gears in a bag for inspection&quot;</em> or <em>&quot;call strictly after 2:00 PM&quot;</em>, record these details in the notes field during initial check-in. This guarantees flawless customer satisfaction upon pickup and cements your workshop&#39;s reputation.</p></div>',33))])}const k=o(d,[["render",p]]);export{v as __pageData,k as default};
